renderer.css:
.phone-shell{width:min(100%,430px);height:100%;max-height:100%;margin:0 auto;background:#07151F;box-shadow:0 30px 80px rgba(34,40,60,.18);display:flex;flex-direction:column;overflow:hidden;color:#F7FDFF;font-family:"Poppins","Segoe UI",Arial,sans-serif;font-size:14px;font-weight:700;letter-spacing:0px;line-height:1.35;text-align:left;}.phone-shell>.app-topbar,.phone-shell>.brand-strip{flex:0 0 auto}.phone-shell>.slider-shell{flex:1 1 auto;min-height:0;display:grid;grid-template-rows:minmax(0,1fr) auto auto;overflow:hidden}.phone-shell>.slider-shell>.slide-window{position:relative;min-height:0;overflow:hidden}.phone-shell>.slider-shell>.slide-window>.slide-track{position:absolute;inset:0;display:flex;min-height:0;align-items:stretch}.phone-shell>.slider-shell>.slide-window>.slide-track>.page-slide{flex:0 0 100%;width:100%;min-width:100%;height:100%;max-height:100%;min-height:0;overflow-x:hidden;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;touch-action:pan-y}.phone-shell>.slider-shell>.progress-shell,.phone-shell>.slider-shell>.slider-controls{flex:0 0 auto}.phone-shell>.empty-ui{flex:1 1 auto;min-height:0;overflow-x:hidden;overflow-y:auto;-webkit-overflow-scrolling:touch;overscroll-behavior:contain}
.app-topbar{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:center;min-height:84px;padding:14px 16px 12px;background:linear-gradient(145deg,#07131C,#6FB6D6),#07131C;color:#fff;box-shadow:0 18px 38px rgba(18,50,70,.16);}
.param-cmd-console{display:flex;align-items:flex-start;gap:8px;width:100%;min-width:0;padding:8px 10px;border-radius:8px;border:1px solid #1F2937;background:#0B0F17}.param-cmd-prompt{flex:0 0 auto;color:#4ADE80;font-size:12px;font-weight:700;line-height:1.45}.param-cmd-input,.param-console-input{flex:1 1 auto;width:100%;min-width:0;min-height:1.45em;height:auto;border:0;background:transparent;color:#E5E7EB;font-family:ui-monospace,Consolas,monospace;font-size:12px;font-weight:600;line-height:1.45;white-space:pre-wrap;overflow-wrap:anywhere;resize:none}
.app-back-btn,.back-btn,.icon-btn{display:inline-flex;align-items:center;justify-content:center;height:42px;border:0;border-radius:999px;background:rgba(255,255,255,.1);color:#fff;box-shadow:inset 0 0 0 1px rgba(255,255,255,.12);}.app-back-btn,.back-btn{width:auto;min-width:42px;padding:0 12px;gap:2px;font-size:13px;font-weight:600;}.icon-btn{width:42px;border-radius:50%;}
.top-title h1{margin:0;color:#fff;font-size:18px;line-height:1.2;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.top-title p{margin:2px 0 0;color:rgba(255,255,255,.68);font-size:12px;line-height:1.25;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.top-actions{display:flex;align-items:center;gap:4px;}
.brand-strip{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;margin:10px 16px 12px;padding:10px 16px;border:0;border-radius:999px;background:#173244;box-shadow:0 10px 28px rgba(15,23,42,.12);color:#F7FDFF;}
.brand-mark{display:inline-flex;align-items:center;justify-content:center;height:32px;padding:2px 4px;border:0;border-radius:6px;background:#fff;overflow:hidden}.brand-mark img{display:block;height:28px;width:auto;max-width:118px;object-fit:contain}.brand-copy strong{display:block;color:#F7FDFF;font-size:14px;line-height:1.2;font-weight:900;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.brand-copy span{display:block;margin-top:2px;color:#C5D7E2;font-size:11px;font-weight:700;}.online-state{display:inline-flex;align-items:center;gap:7px;color:#10B981;font-size:12px;font-weight:900;}
.page-slide{padding:18px 18px 4px}.slide-hero{position:relative;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:end;min-height:112px;margin-bottom:14px;padding:18px;border-radius:calc(18px + 6px);background:linear-gradient(145deg,#07131C,#6FB6D6);color:#fff;box-shadow:0 18px 38px rgba(18,50,70,.16);overflow:hidden;}.slide-hero:after{content:"";position:absolute;right:-36px;top:-36px;width:112px;height:112px;border-radius:50%;border:24px solid rgba(209,250,255,.16);}
.slide-hero-kicker{display:inline-flex;align-items:center;gap:6px;margin-bottom:8px;color:rgba(255,255,255,.72);font-size:11px;font-weight:800;text-transform:uppercase}.slide-hero h2{margin:0;color:#fff;font-size:22px;line-height:1.1;font-weight:900;overflow-wrap:anywhere}.slide-hero p{margin:6px 0 0;color:rgba(255,255,255,.68);font-size:12px;font-weight:700}.slide-count{position:relative;z-index:1;display:inline-flex;flex-direction:column;align-items:center;justify-content:center;width:58px;height:58px;border-radius:20px;background:rgba(255,255,255,.12);box-shadow:inset 0 0 0 1px rgba(255,255,255,.14);}
.device-card,.param-card{border:1px solid #36566A;border-radius:18px;background:#173244;box-shadow:0 12px 28px rgba(18,50,70,.1);}.name-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;padding:16px;}.field-label{display:block;margin-bottom:5px;color:#C5D7E2;font-size:11px;line-height:1;font-weight:800;text-transform:uppercase;letter-spacing:.02em}.field-value{display:block;min-width:0;color:#F7FDFF;font-size:16px;line-height:1.25;font-weight:700;overflow-wrap:anywhere}.edit-link{color:#7EE2A8;font-size:12px;font-weight:800;text-decoration:none;}
.param-list{display:flex;flex-direction:column;gap:14px;margin-top:0;padding:0;border:0;background:transparent;overflow:visible}.param-group-card{display:flex;flex-direction:column;gap:0;padding:10px 10px 8px;border:1px solid #36566A;border-radius:18px;background:#173244;overflow:hidden}.param-card.is-grouped-component{background:transparent;border:0;box-shadow:none;border-radius:0;min-height:44px}.param-card{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:12px;align-items:center;min-height:66px;padding:16px;position:relative;overflow:hidden;}.param-card.layout-stacked{display:flex;flex-direction:column;align-items:stretch;min-height:0;overflow:visible;padding-bottom:calc(16px + 4px)}.param-card.layout-stacked>.param-main-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:12px;align-items:center;width:100%}.param-card.layout-stacked>.range-visual,.param-card.layout-stacked>.needle-gauge-visual,.param-card.layout-stacked>.pointer-gauge-visual,.param-card.layout-stacked>.power-gauge-visual,.param-card.layout-stacked>.segmented-visual,.param-card.layout-stacked>.linear-gauge-visual,.param-card.layout-stacked>.registered-visual{width:100%;max-width:100%;flex:0 0 auto;overflow:visible;box-sizing:border-box}.needle-gauge-visual,.pointer-gauge-visual,.power-gauge-visual{width:100%;display:flex;flex-direction:column;align-items:center;overflow:visible}.power-gauge-svg-host{width:100%;max-width:240px;margin:0 auto;display:flex;justify-content:center;overflow:visible}.needle-gauge-svg,.power-gauge-svg{width:100%;max-width:240px;height:auto;min-height:148px;display:block;overflow:visible}.param-card:before{content:"";position:absolute;left:0;top:14px;bottom:14px;width:3px;border-radius:0 999px 999px 0;background:linear-gradient(180deg,#6FB6D6,#7EE2A8)}.param-icon{border:0;display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:50%;background:rgba(37,99,235,.14);color:#7EE2A8;}.param-meta{display:flex;align-items:center;justify-content:center;gap:5px;min-width:42px;height:34px;padding:0 8px;border-radius:999px;background:rgba(37,99,235,.12);color:#7EE2A8;font-size:12px;font-weight:900;}.toggle-visual{position:relative;width:34px;height:18px;border-radius:999px;background:#4A6473;}.toggle-visual:after{content:"";position:absolute;top:-1px;right:0;width:20px;height:20px;border-radius:50%;background:#7EE2A8;box-shadow:0 4px 9px rgba(37,99,235,.24);}.range-visual{grid-column:1/-1;margin-top:10px;width:100%}.range-values{display:flex;justify-content:space-between;color:#F7FDFF;font-size:10px;font-weight:600}.range-line{position:relative;height:3px;margin:12px 8px 8px;border-radius:999px;background:#7EE2A8}.range-line:before{content:"";position:absolute;left:-6px;top:-9px;width:22px;height:22px;border-radius:50%;background:#7EE2A8}
.progress-shell{margin:0 18px 8px;height:5px;border-radius:999px;background:rgba(106,142,174,.18);overflow:hidden}.progress-bar{height:100%;border-radius:inherit;background:linear-gradient(90deg,#6FB6D6,#7EE2A8)}.slider-controls{display:grid;grid-template-columns:48px 1fr 48px;gap:10px;align-items:center;margin:6px 18px 0;padding:12px;border:1px solid rgba(106,142,174,.28);border-radius:20px;background:rgba(255,255,255,.72);box-shadow:0 12px 28px rgba(18,50,70,.1);}.slide-arrow{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border:1px solid rgba(106,142,174,.28);border-radius:50%;background:#07131C;color:#fff}.page-buttons{display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none}.page-buttons::-webkit-scrollbar{display:none}.page-button{flex:0 0 auto;min-width:34px;height:34px;padding:0 10px;margin:8px;border:1px solid rgba(106,142,174,.28);border-radius:999px;background:#fff;color:#F7FDFF;font-size:13px;font-weight:900}.page-button.is-active{border-color:#7EE2A8;background:linear-gradient(135deg,#6FB6D6,#7EE2A8);color:#fff;}
